function PropSetToStr(Inputs:PropertySet)
{
	var res = "";
	var bs = TheApplication().GetService(""+"XML Converter");
	var out = TheApplication().NewPropertySet();
	bs.InvokeMethod("PropSetToXML",Inputs, out);
	res = out.GetValue();
	bs = null;
	out = null;
	return res;
}

function Service_PreInvokeMethod (MethodName, Inputs, Outputs)
{
	if(MethodName == "getUserDatabyPhone") {
	this.getUserDatabyPhone(Inputs, Outputs);
	return (CancelOperation);
	}

	if(MethodName == "createActivity") {
	this.createActivity(Inputs, Outputs);
	return (CancelOperation);
	}

	if (MethodName == "originate") {
        this.originate(Inputs, Outputs);
        return (CancelOperation);
    }

	if (MethodName == "callcontrol") {
        this.callcontrol(Inputs, Outputs);
        return (CancelOperation);
    }

	if (MethodName == "checkUserPhone") {
        this.checkUserPhone(Inputs, Outputs);
        return (CancelOperation);
    }

	return (ContinueOperation);
}

function callcontrol(Inputs: PropertySet, Outputs: PropertySet) 
{

try
{
var svc:Service = TheApplication().GetService(""+"EAI HTTP Transport");
var srvConverter:Service = TheApplication().GetService("EAI JSON Converter");
var inp:PropertySet = TheApplication().NewPropertySet();
var oup:PropertySet = TheApplication().NewPropertySet();
var oup1:PropertySet = TheApplication().NewPropertySet();
var integrator_id = getSysPref("KyivstarIntId");
var sToken = getSysPref("KyivstarToken");
var sUrl = "https://fmc.kyivstar.ua/api/fmc/v1/callcontrol?integrator_id="+integrator_id+"";
var callControlId = Inputs.GetProperty("callControlId");
var action = Inputs.GetProperty("action");

var request = "{\"call_control_id\":\"" + callControlId + "\",\"action\":\"" + action + "\"}";

	inp.SetProperty("HTTPRequestURLTemplate", sUrl);
	inp.SetProperty("HTTPRequestMethod", "POST");
	inp.SetProperty("HTTPContentType", "application/json");
	inp.SetProperty("HDR.Authorization", "Bearer " + sToken);
	inp.SetProperty("CharSetConversion", "UTF-8");
	inp.SetProperty("HTTPSleepTime", "10000");
	inp.SetValue(request);

	this.saveLogWithLevel(callControlId, this.PropSetToStr(inp), "callcontrol", "Start", "request", "5", "Business Service", "SPXxxxxxKyivstarBS", "SPXxxxxxKyivstarBS.callcontrol");
	svc.InvokeMethod("SendReceive", inp, oup);
	this.saveLogWithLevel(callControlId, this.PropSetToStr(oup), "callcontrol", "End", "responce", "5", "Business Service", "SPXxxxxxKyivstarBS", "SPXxxxxxKyivstarBS.callcontrol");

}
catch(e)
{
Outputs.SetProperty("errorCode", "1");
Outputs.SetProperty("errorMsg", "" + e);
this.saveLogWithLevel(callControlId, "error:" + e, "callcontrol", "error", "request", "5", "Business Service", "SPXxxxxxKyivstarBS", "SPXxxxxxKyivstarBS.callcontrol");
}
finally
{
if (Outputs.GetProperty("errorCode") == "")
{
Outputs.SetProperty("errorCode", "0");
}
inp = null;
oup = null;
svc = null;
}


}

function checkUserPhone(Inputs: PropertySet, Outputs: PropertySet) 
{
var BO = TheApplication().GetBusObject("Employee");
var BC = BO.GetBusComp("Employee");
var userId = Inputs.GetProperty("userId");
var Phone = "";

try
{
	BC.SetViewMode(AllView);
	BC.ActivateField("Cell Phone #");
	BC.ClearToQuery();
	BC.SetSearchExpr("[Id] = '"+userId+"'");
	BC.ExecuteQuery(ForwardOnly);
	if(BC.FirstRecord())
	{
	Phone = BC.GetFieldValue("Cell Phone #");
	}
}
catch(e)
{
Outputs.SetProperty("errorCode", "1");
Outputs.SetProperty("errorMsg", "" + e);
}
finally
{
if (Outputs.GetProperty("errorCode") == "")
{
Outputs.SetProperty("errorCode", "0");
Outputs.SetProperty("phone", Phone);
}
BC = null;
BO = null;
}

}

function createActivity(Inputs: PropertySet, Outputs: PropertySet)
{
//var ContactId = Inputs.GetProperty("ContactId");
var ContactId = "";
var Desc = Inputs.GetProperty("Desc");
var OwnerId = Inputs.GetProperty("OwnerId");
var Direction = Inputs.GetProperty("Direction");
var PhoneNum = Inputs.GetProperty("PhoneNum");
var CallId = Inputs.GetProperty("CallId");
var CallControlId = Inputs.GetProperty("CallControlId");
var ActionId = "";
var sTimeStamp:chars;
Clib.strftime(sTimeStamp,"%m/%d/%Y %H:%M:%S",new Date());
var DateTime = sTimeStamp;

var BO: BusObject;
var bcAction: BusComp;
var bcContact: BusComp;
var bcPick: BusComp;
var ErrorCode = "0";
var ErrorMsg = "";

var sType="";
var bcFind : BusComp;
var iCnt = 0;
var sFoundId = "";
var isRec = false;
var bcMVG : BusComp;
var bcAssoc : BusComp;

try
{
	if (Direction == "incoming")
		{
			Direction = "Вхідний";
		}
	else
		{
			Direction = "Вихідний";
		}

	sType= TheApplication().InvokeMethod("LookupValue", "SP_ACTIVITY_TYPE", "Call");

	Desc = "Вхідний дзвінок " + PhoneNum;
	// пошук ФО Contact

	if (PhoneNum != "" && PhoneNum != null)
	{
		BO = TheApplication().GetBusObject("Contact");
		bcFind = BO.GetBusComp("Contact");

		bcFind.SetViewMode(AllView);
		bcFind.ActivateField("SP LOV Primary Phone Number");

		bcFind.ClearToQuery();
		bcFind.SetSearchExpr("[SP LOV Primary Phone Number] = '" + PhoneNum + "'");
		bcFind.ExecuteQuery(ForwardOnly);

		iCnt = 0;
		sFoundId = "";
		isRec = bcFind.FirstRecord();

		while(isRec)
		{
			iCnt++;

			if(iCnt == 1)
			{
				sFoundId = bcFind.GetFieldValue("Id");
			}

			isRec = bcFind.NextRecord();
		}

		if(iCnt == 1)
		{
			ContactId = sFoundId;
		}
		else if(iCnt > 1)
		{
			Desc = Desc + "\nЗнайдено " + iCnt + " фізичних осіб з даним номером";
		}

		BO = null;
		bcFind = null;
	}

	if (ContactId != "" && ContactId != null)
	{
		BO = TheApplication().GetBusObject("Contact");
		bcContact = BO.GetBusComp("Contact");
		bcAction = BO.GetBusComp("Action");

		bcContact.SetViewMode(AllView);
		bcContact.ClearToQuery();
		bcContact.SetSearchExpr("[Id] = '" + ContactId + "'");
		bcContact.ExecuteQuery(ForwardOnly);

		if (!bcContact.FirstRecord())
		{
			ErrorCode = "1";
			ErrorMsg = "Контакт не знайдено";
			return;
		}
	}
	else
	{
		BO = TheApplication().GetBusObject("Action");
		bcAction = BO.GetBusComp("Action");
	}

	bcAction.InvokeMethod("SetAdminMode", "TRUE");
	bcAction.SetViewMode(AllView);
	bcAction.ActivateField("Priority");
	bcAction.ActivateField("SP Channel");
	bcAction.ActivateField("Description");
	bcAction.ActivateField("SP Direction");
	bcAction.ActivateField("SP Phone Number");
	bcAction.ActivateField("SP Call Id");
	bcAction.ActivateField("SP Call Control Id");

	bcAction.ActivateField("SP Activity Date");
	bcAction.ActivateField("Start Time");
	bcAction.ActivateField("End Time");
	bcAction.ActivateField("End Date");
	bcAction.ActivateField("Due Date");

	bcAction.ActivateField("Contact Id");
	bcAction.ActivateField("Account Id");
	bcAction.ActivateField("Primary Owner Id");

	bcAction.ClearToQuery();
	bcAction.SetSearchExpr("[SP Call Control Id] = '" + CallControlId + "'");
	bcAction.ExecuteQuery(ForwardOnly);

	if (bcAction.FirstRecord())
	{
		// Повторный вызов = конец звонка
//яку дату краще?
		bcAction.SetFieldValue("End Time", DateTime);
		bcAction.SetFieldValue("End Date", DateTime);
		bcAction.SetFieldValue("Due Date", DateTime);

		bcAction.WriteRecord();
	}
	else
	{
		// Первый вызов = начало звонка
		bcAction.NewRecord(NewAfter);

		bcAction.SetFieldValue("Category", TheApplication().InvokeMethod("LookupValue", "TODO_TYPE", "General"));
		bcAction.SetFieldValue("Type", sType);
		bcAction.SetFieldValue("SP Channel", TheApplication().InvokeMethod("LookupValue", "SP_ACTIVITY_CHANNEL", "Phone"));

//яку дату краще?
		bcAction.SetFieldValue("SP Activity Date", DateTime);	
		bcAction.SetFieldValue("Start Time", DateTime);

		bcAction.SetFieldValue("SP Direction", Direction);
		bcAction.SetFieldValue("SP Phone Number", PhoneNum);
		bcAction.SetFieldValue("SP Call Id", CallId);
		bcAction.SetFieldValue("SP Call Control Id", CallControlId);
		if(OwnerId != "" && OwnerId != null)
		{
			bcAction.SetFieldValue("Primary Owner Id", OwnerId);
		}

		// Пошук ЮО Account


		iCnt = 0;
		sFoundId = "";

		bcFind = BO.GetBusComp("Account");

		bcFind.SetViewMode(AllView);
		bcFind.ActivateField("SP LOV Primary Phone Number");

		bcFind.ClearToQuery();
		bcFind.SetSearchExpr("[SP LOV Primary Phone Number] = '" + PhoneNum + "'");
		bcFind.ExecuteQuery(ForwardOnly);

		isRec = bcFind.FirstRecord();

		while(isRec)
		{
			iCnt++;

			if(iCnt == 1)
			{
				sFoundId = bcFind.GetFieldValue("Id");
			}

			isRec = bcFind.NextRecord();
		}

		if(iCnt == 1)
		{
			bcAction.SetFieldValue("Account Id", sFoundId);
		}
		else if(iCnt > 1)
		{
			Desc = Desc + "\nЗнайдено " + iCnt + " юридичних осіб з даним номером";
		}

		bcAction.SetFieldValue("Description", Desc);
		bcAction.WriteRecord();
	}

	ActionId = bcAction.GetFieldValue("Id");

}
catch(e)
{
ErrorCode = "1";
ErrorMsg = e.toString();
}
finally
{
if(bcAction != null)
{
	bcAction.InvokeMethod("SetAdminMode", "FALSE");
}
Outputs.SetProperty("ActionId", ActionId);
Outputs.SetProperty("ErrorCode", ErrorCode);
Outputs.SetProperty("ErrorMsg", ErrorMsg);
BO = null;
bcMVG  = null;
bcAssoc  = null;
bcAction = null;
bcFind = null;
bcContact = null;
}


}

function getSysPref(name)
{
	try
	{		
	    var sRet:chars = "";
		var boSysPref:BusObject = TheApplication().GetBusObject("System Preferences");
		var bcSysPref:BusComp = boSysPref.GetBusComp("System Preferences");

		bcSysPref.ActivateField("Name");
		bcSysPref.ActivateField("Value");
        bcSysPref.SetViewMode(AllView);		
		bcSysPref.SetSearchExpr("[Name] = '" + name + "'");
		bcSysPref.ExecuteQuery(ForwardOnly);
		if (bcSysPref.FirstRecord())
		{
			sRet = bcSysPref.GetFieldValue("Value");
		}		
	}finally{
		bcSysPref = null;		
		boSysPref = null;
	}
	return (sRet);
}

function getUserDatabyPhone(Inputs: PropertySet, Outputs: PropertySet)
{
var BOCon = TheApplication().GetBusObject("Contact");
var BCCon = BOCon.GetBusComp("Contact");
var BOAcc = TheApplication().GetBusObject("Account");
var BCAcc = BOAcc.GetBusComp("Account");
var Phone = Inputs.GetProperty("PhoneNumber");
var FullName = "";
var ErrorCode = "0";
var ErrorMsg = "";
var psContacts = TheApplication().NewPropertySet();
var psAccounts = TheApplication().NewPropertySet();

try
{
	BCCon.SetViewMode(AllView);
	BCCon.ActivateField("SP Primary Phone Number");
	BCCon.ActivateField("SP Full Name");
	BCCon.ClearToQuery();
	BCCon.SetSearchExpr("EXISTS ([SP Primary Phone Number] = '"+Phone+"')");
	BCCon.ExecuteQuery(ForwardOnly);
	var recCon = BCCon.FirstRecord();
	var i = 0;
	psContacts.SetType("ListOfcontacts");
	while(recCon && i < 3)
	{
	var psContact = TheApplication().NewPropertySet();
	psContact.SetType("contact");
	psContact.SetProperty("ContactId", BCCon.GetFieldValue("Id"));
	psContact.SetProperty("FullName", BCCon.GetFieldValue("SP Full Name"));
	psContacts.AddChild(psContact);
	i++;
	recCon = BCCon.NextRecord();
	}

	BCAcc.SetViewMode(AllView);
	BCAcc.ActivateField("SP Primary Phone Number");
	BCAcc.ActivateField("Name");
	BCAcc.ClearToQuery();
	BCAcc.SetSearchExpr("EXISTS ([SP Primary Phone Number] = '"+Phone+"')");
	BCAcc.ExecuteQuery(ForwardOnly);
	var recAcc = BCAcc.FirstRecord();
	var y = 0;
	psAccounts.SetType("ListOfaccounts");
	while(recAcc && y < 3)
	{
	var psAccount = TheApplication().NewPropertySet();
	psAccount.SetType("account");
	psAccount.SetProperty("AccountId", BCAcc.GetFieldValue("Id"));
	psAccount.SetProperty("FullName", BCAcc.GetFieldValue("Name"));
	psAccounts.AddChild(psAccount);
	y++;
	recAcc = BCAcc.NextRecord();
	}

}
catch(e)
{
ErrorCode = "1";
ErrorMsg = e.toString();
}
finally
{
Outputs.SetProperty("ErrorCode", ErrorCode);
Outputs.SetProperty("ErrorMsg", ErrorMsg);
Outputs.AddChild(psContacts);
Outputs.AddChild(psAccounts);
BCCon = BCAcc = BCAcc = BOCon = null;
}

}

function getUserDataby_Phone(phone)
{
var BO = TheApplication().GetBusObject("Contact");
var BC = BO.GetBusComp("Contact");
var ContactId = "";

	BC.SetViewMode(AllView);
	BC.ActivateField("SP Primary Phone Number");
	BC.ActivateField("SP Full Name");
	BC.ClearToQuery();
	BC.SetSearchExpr("EXISTS ([SP Primary Phone Number] = '"+phone+"')");
	BC.ExecuteQuery(ForwardOnly);
	var countReq = BC.CountRecords();
	if(countReq < 2)
	{
		if(BC.FirstRecord())
		{
		ContactId = BC.GetFieldValue("Id");
		}
	}

return ContactId;
}

function getUserPhonebyId(UserId)
{
var BO = TheApplication().GetBusObject("Employee");
var BC = BO.GetBusComp("Employee");
var userPhone = "";

	BC.SetViewMode(AllView);
	BC.ActivateField("Cell Phone #");
	BC.ClearToQuery();
	BC.SetSearchExpr("[Id] = '"+UserId+"'");
	BC.ExecuteQuery(ForwardOnly);
	if(BC.FirstRecord())
	{
		userPhone = BC.GetFieldValue("Cell Phone #");
	}

return userPhone;
}

function invokeCreateActivity(ContactId,Desc,OwnerId,Direction,PhoneNum,CallId,CallControlId)
{
var svc = TheApplication().GetService("SPXxxxxxKyivstarBS");
var psInputs = TheApplication().NewPropertySet();
var psOutputs = TheApplication().NewPropertySet();

psInputs.SetProperty("ContactId",ContactId);
psInputs.SetProperty("Desc",Desc);
psInputs.SetProperty("OwnerId",OwnerId);
psInputs.SetProperty("Direction",Direction);
psInputs.SetProperty("CallId",CallId);
psInputs.SetProperty("PhoneNum",PhoneNum);
psInputs.SetProperty("CallControlId",CallControlId);

svc.InvokeMethod("createActivity", psInputs, psOutputs);
}
